   AND ATTR_NM = #{attrNm}

UPDATE TB_DATA_MODEL_OBJ
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt}
 WHERE DM_ID = #{dmId}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND OBJ_NM = #{objNm}
